const incoming = $input.first()?.json ?? {};
const cases = Array.isArray(incoming.cases) ? incoming.cases : [];
const rules = {
  "C-17": {
    priority: "high",
    intervention_required: true,
    priority_requires_approval: true,
    discrepancy: "В CRM документы ожидаются, а сотрудник сообщает об отправке фотографий руководителю; получение и регистрация не подтверждены.",
    unknowns: ["Получил ли руководитель документы", "Зарегистрированы ли документы в системе"],
    fallback_next_action: "Проверить документы и завершение обязательных этапов оформления.",
    expected: { priority: "high", intervention_required: true }
  },
  "C-24": {
    priority: "high",
    intervention_required: true,
    priority_requires_approval: true,
    discrepancy: "Сотрудник сообщает об обсуждении увольнения, но подтверждения руководителя в CRM нет.",
    unknowns: ["Подтвердил ли руководитель увольнение установленным способом", "Соблюдена ли процедура увольнения"],
    fallback_next_action: "Оперативно проверить подтверждение у руководителя и соблюдение процедуры сегодня.",
    expected: { priority: "high", intervention_required: true }
  },
  "P-08": {
    priority: "high",
    intervention_required: true,
    priority_requires_approval: true,
    discrepancy: "Срок доставки в CRM — до 10:00, а курьер сообщает о задержке минимум до 13:00.",
    unknowns: ["Подтверждён ли новый срок доставки"],
    fallback_next_action: "Уточнить новый срок у ответственного и при необходимости уведомить получателя.",
    expected: { priority: "high", intervention_required: true }
  },
  "P-09": {
    priority: "low",
    intervention_required: false,
    priority_requires_approval: false,
    discrepancy: null,
    unknowns: [],
    fallback_next_action: "Дополнительное вмешательство не требуется, если нет других обязательных этапов.",
    expected: { priority: "low", intervention_required: false }
  }
};
const rows = cases.length ? cases : [{ case_id: null, facts: [] }];
return rows.map((raw) => {
  const errors = [];
  if (!raw || typeof raw.case_id !== "string") errors.push("case_id отсутствует или не является строкой");
  if (!Array.isArray(raw?.facts) || raw.facts.length === 0) errors.push("facts должен содержать хотя бы один факт");
  const facts = Array.isArray(raw?.facts) ? raw.facts : [];
  facts.forEach((fact, index) => {
    if (!fact || typeof fact.text !== "string" || typeof fact.source !== "string" || typeof fact.original_value !== "string") {
      errors.push("Некорректный факт с индексом " + index + ": нужны text, source и original_value");
    }
  });
  const rule = rules[raw?.case_id] ?? null;
  if (!rule) errors.push("Для case_id нет правила приоритета");
  return { json: {
    case_id: raw?.case_id ?? null,
    process: raw?.process ?? null,
    facts,
    input_valid: errors.length === 0,
    validation_errors: errors,
    priority: rule?.priority ?? "unknown",
    intervention_required: rule?.intervention_required ?? true,
    priority_requires_approval: rule?.priority_requires_approval ?? true,
    discrepancy: rule?.discrepancy ?? null,
    unknowns: rule?.unknowns ?? [],
    fallback_next_action: rule?.fallback_next_action ?? "Передать кейс человеку для проверки исходных данных и процесса.",
    expected: rule?.expected ?? null
  }};
});

const rules = $("Apply Rules & Validate").all();
const responses = $input.all();
const cases = [];
const errors = [];

for (let i = 0; i < rules.length; i++) {
  const base = rules[i]?.json ?? {};
  const modelItem = responses[i]?.json ?? {};
  let modelStatus = "ok";
  let parsed = null;
  let rawText = modelItem.text ?? modelItem.output ?? modelItem.response ?? modelItem.message?.content ?? null;

  if (!base.input_valid) {
    modelStatus = "skipped_invalid_input";
  } else if (modelItem.error || modelItem.errorMessage || modelItem.message?.error) {
    modelStatus = "model_error";
  } else {
    if (typeof rawText === "object" && rawText !== null) {
      rawText = rawText.text ?? rawText.content ?? JSON.stringify(rawText);
    }
    if (typeof rawText === "string") {
      const fence = String.fromCharCode(96).repeat(3);
      let clean = rawText.trim();
      if (clean.startsWith(fence)) clean = clean.slice(fence.length).replace(/^(?:json)?\s*/i, "");
      if (clean.endsWith(fence)) clean = clean.slice(0, -fence.length).trim();
      try {
        parsed = JSON.parse(clean);
      } catch (e) {
        modelStatus = "invalid_json";
      }
    } else {
      modelStatus = "invalid_json";
    }
    if (
      modelStatus === "ok" &&
      (!parsed ||
        typeof parsed.explanation !== "string" ||
        typeof parsed.recommended_next_step !== "string" ||
        !parsed.recommended_next_step.trim())
    ) {
      modelStatus = "invalid_json";
    }
  }

  const fallbackUsed = modelStatus !== "ok";
  const nextAction = fallbackUsed
    ? base.fallback_next_action
    : parsed.recommended_next_step.trim();
  const explanation = fallbackUsed
    ? modelStatus === "model_error"
      ? "Модель не ответила; показаны факты и действие по прозрачному правилу."
      : modelStatus === "invalid_json"
        ? "Ответ модели не прошёл проверку JSON; показаны факты и действие по прозрачному правилу."
        : "Входные данные не прошли проверку; требуется ручная проверка."
    : parsed.explanation.trim();

  const acceptance = base.expected
    ? {
        priority_matches: base.priority === base.expected.priority,
        intervention_matches: base.intervention_required === base.expected.intervention_required,
      }
    : { priority_matches: false, intervention_matches: false };

  const caseErrors = [];
  if (!base.input_valid) {
    caseErrors.push({ type: "input_validation", details: base.validation_errors });
    errors.push({ case_id: base.case_id, type: "input_validation", details: base.validation_errors });
  }
  if (modelStatus === "model_error" || modelStatus === "invalid_json") {
    caseErrors.push({ type: modelStatus });
    errors.push({ case_id: base.case_id, type: modelStatus });
  }

  const statusLabel = !base.input_valid
    ? "⚠️ Ошибка данных - проверить"
    : base.intervention_required
      ? fallbackUsed
        ? "🔴 Требует вмешательства - fallback"
        : "🔴 Требует вмешательства"
      : fallbackUsed
        ? "🟠 Проверить ответ модели"
        : "🟢 Вмешательство не требуется*";

  const facts = Array.isArray(base.facts) ? base.facts : [];
  const factsSummary = facts
    .map((fact) => {
      const time = fact.observed_at ? " (время источника: " + fact.observed_at + ")" : "";
      return fact.source + ": " + fact.text + time;
    })
    .join("\n");

  cases.push({
    case_id: base.case_id,
    status: statusLabel,
    intervention_required: base.intervention_required,
    priority: base.priority,
    priority_requires_approval: base.priority_requires_approval,
    facts_summary: factsSummary,
    facts,
    discrepancy: base.discrepancy,
    unknowns: base.unknowns,
    explanation,
    next_action: nextAction,
    requires_human_review: true,
    model_status: modelStatus,
    expected: base.expected,
    acceptance,
    validation_errors: base.validation_errors,
    fallback_used: fallbackUsed,
    case_errors: caseErrors,
  });
}

const runSummary = {
  case_count: cases.length,
  all_input_valid: cases.every((item) => item.validation_errors.length === 0),
  all_expected_rules_match: cases.every(
    (item) => item.acceptance.priority_matches && item.acceptance.intervention_matches
  ),
  model_success_count: cases.filter((item) => item.model_status === "ok").length,
  error_count: errors.length,
  human_review_required: cases.some((item) => item.requires_human_review),
};
const runSummaryText =
  "Кейсов: " + runSummary.case_count +
  "; правила совпали: " + cases.filter((item) => item.acceptance.priority_matches && item.acceptance.intervention_matches).length + "/" + runSummary.case_count +
  "; ответы модели: " + runSummary.model_success_count + "/" + runSummary.case_count +
  "; ошибок: " + runSummary.error_count;

return cases.map((item) => ({
  json: {
    ...item,
    run_summary: runSummaryText,
    run_metrics: runSummary,
    errors,
  },
}));
